SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "唐昭宗在南山十余日，随驾避乱士民每天相互惊呼邠岐军到了。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p037·原文件第42行", "note": "原文：上在南山旬馀，士民从车驾避乱者日相惊曰：“邠、岐兵至矣！”；核对说明：士民相惊是惊报，不独认邠岐兵每天真到；旬余不反算精确起止日。", "status": "draft", "id": "21e01d28-7058-53bf-a6f7-554315a6d88a", "subject_id": "57aae869-1aa7-5566-84be-0aea10a45881", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "895年七月帝在南山旬余期间", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p037·原文件第42行", "note": "原文：上在南山旬馀，士民从车驾避乱者日相惊曰：“邠、岐兵至矣！”；核对说明：士民相惊是惊报，不独认邠岐兵每天真到；旬余不反算精确起止日。", "status": "draft", "id": "de2a93f5-54ee-5eaf-8071-c4fb8081b935", "subject_id": "57aae869-1aa7-5566-84be-0aea10a45881", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李杰：南山避乱者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p037·原文件第42行", "note": "原文：上在南山旬馀，士民从车驾避乱者日相惊曰：“邠、岐兵至矣！”上遣延王戒丕诣河中，趣李克用令进兵。壬午，克用发河中。八月，上遣供奉官张承业诣克用军。承业，同州人，屡奉使于克用，因留监其军。己丑，克用进军渭桥，遣其将李存贞为前锋；辛卯，拨永寿，又遣史俨将三千骑诣石门侍卫。癸已，遣李存信、李存审会保大节度使李思孝攻王行瑜黎园寨，擒其将王令陶等，献于行在。思孝本姓拓跋，思恭之弟也。李茂贞惧，斩李继鹏，传首行在，上表请罪，且遣使求和于克用。上复遣延王戒丕、丹王允谕克用，令且赦茂贞，并力讨行瑜，俟其殄平，当更与卿议之。且命二王拜克用为兄。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "93472bfb-8bdc-57ed-b49a-6e003ae01630", "subject_id": "48935190-c754-5bda-bdcd-382c77cb2de0", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "唐昭宗：南山避乱者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p037·原文件第42行", "note": "原文：上在南山旬馀，士民从车驾避乱者日相惊曰：“邠、岐兵至矣！”；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "3ea06f3c-ed5d-5e18-afd8-856a491ca033", "subject_id": "1e47872a-6450-5dd1-b95c-47a7169518a6", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subj